/** Native viewport/resource/effect tests, not physical vision or acoustic accuracy claims. */
@RunWith(AndroidJUnit4.class)
public class ImageSelectionTest {
 private final Instrumentation instrumentation=InstrumentationRegistry.getInstrumentation();private Activity activity;private NotesController controller;private Context isolated;private java.io.File fixture;private final java.util.Queue<String> messages=new java.util.concurrent.ConcurrentLinkedQueue<>();private OfflineOcr.Scan scan;private Dialog dialog;
 @Before public void setup(){activity=instrumentation.startActivitySync(new Intent(instrumentation.getTargetContext(),NotesActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Bitmap bitmap=Bitmap.createBitmap(1000,500,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(bitmap);c.drawColor(Color.WHITE);Paint p=new Paint();p.setColor(Color.RED);c.drawRect(500,250,1000,500,p);p.setColor(Color.BLACK);p.setTextSize(80);c.drawText("ONE",100,130,p);c.drawText("25",400,130,p);c.drawText("+",100,330,p);c.drawText("😀",300,330,p);scan=new OfflineOcr.Scan(new OfflineOcr.Result("ONE 25\n+ 😀","eng",90,1000,500,Arrays.asList(new ImageTextSelection.Word("ONE",.1f,.1f,.3f,.3f,1),new ImageTextSelection.Word("25",.4f,.1f,.5f,.3f,1),new ImageTextSelection.Word("+",.1f,.5f,.2f,.7f,2),new ImageTextSelection.Word("😀",.3f,.5f,.4f,.7f,2))),bitmap);}
 @After public void cleanup(){instrumentation.runOnMainSync(()->{if(dialog!=null)dialog.dismiss();if(controller!=null)controller.close();if(activity!=null)activity.finish();});if(scan!=null)scan.close();}
 private void main(Runnable action){instrumentation.runOnMainSync(action);}
 private View named(View root,String name){if(root instanceof TextView && name.contentEquals(((TextView)root).getText()))return root;if(root.getContentDescription()!=null && name.contentEquals(root.getContentDescription()))return root;if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++){View found=named(((ViewGroup)root).getChildAt(i),name);if(found!=null)return found;}return null;}
 private ImageTextSelectionView viewport(View root){if(root instanceof ImageTextSelectionView)return (ImageTextSelectionView)root;if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++){ImageTextSelectionView found=viewport(((ViewGroup)root).getChildAt(i));if(found!=null)return found;}return null;}
 private void show(java.util.function.Consumer<String> text,java.util.function.Consumer<RectF> image){main(()->dialog=ImageTextSelectionDialog.show(new NotesDesign(activity,false),scan,text,image));instrumentation.waitForIdleSync();}
 private void click(String name){main(()->{View target=named(dialog.getWindow().getDecorView(),name);assertNotNull(name,target);assertTrue(name,target.isEnabled());target.performClick();});instrumentation.waitForIdleSync();}
 @Test public void compactSecondaryToolsRemainAccessibleAndReadAreaIsVisible(){show(text->{},box->{});main(()->{
  View root=dialog.getWindow().getDecorView();float minimum=48*activity.getResources().getDisplayMetrics().density;
  for(String name:new String[]{"Select all","Clear","Choose words","Copy selected text"}){View tool=named(root,name);assertNotNull(name,tool);assertEquals(name,tool.getContentDescription().toString());assertTrue(name,tool.getLayoutParams().width>=minimum-1);assertTrue(name,tool.getLayoutParams().height>=minimum-1);}
  assertNull("Redundant zoom action removed; pinch remains available",named(root,"Reset zoom"));View read=named(root,"Read this area");assertNotNull(read);assertFalse("Reading action must not be in scrolling secondary toolbar",read.getParent().getParent() instanceof HorizontalScrollView);Rect shown=new Rect();assertTrue(read.getGlobalVisibleRect(shown));assertEquals(read.getHeight(),shown.height());
 });}
 @Test public void copySelectedTextDoesNotSaveOrDismissAndClearDisablesCopy(){boolean[] changed={false};show(text->changed[0]=true,box->changed[0]=true);click("Copy selected text");main(()->{android.content.ClipboardManager clipboard=(android.content.ClipboardManager)activity.getSystemService(Context.CLIPBOARD_SERVICE);assertNotNull(clipboard.getPrimaryClip());assertEquals("ONE 25\n+ 😀",clipboard.getPrimaryClip().getItemAt(0).getText().toString());assertTrue(dialog.isShowing());assertFalse(changed[0]);});click("Clear");main(()->assertFalse(named(dialog.getWindow().getDecorView(),"Copy selected text").isEnabled()));}
 @Test public void selectedTextIsReviewedWithoutInventingObjectNames(){String[] value={null};show(text->value[0]=text,box->fail("unexpected image save"));main(()->assertEquals("ONE 25\n+ 😀",((TextView)named(dialog.getWindow().getDecorView(),"Selected text preview")).getText().toString()));click("Use selected text");assertEquals("ONE 25\n+ 😀",value[0]);assertFalse(dialog.isShowing());}
 @Test public void clearDisablesExtractionUntilAccessibleWordSelectionChanges(){show(text->{},box->{});click("Clear");main(()->{assertFalse(named(dialog.getWindow().getDecorView(),"Use selected text").isEnabled());ImageTextSelectionView view=viewport(dialog.getWindow().getDecorView());view.selection.toggle(1);view.refresh();assertTrue(named(dialog.getWindow().getDecorView(),"Use selected text").isEnabled());assertEquals("25",view.selection.text());assertEquals("25",((TextView)named(dialog.getWindow().getDecorView(),"Selected text preview")).getText().toString());});}
 @Test public void draggingKeepsOnlyIntersectingWordsAndTheOriginalPixels(){show(text->{},box->{});main(()->{ImageTextSelectionView view=viewport(dialog.getWindow().getDecorView());assertTrue(view.getWidth()>0);assertTrue(view.getHeight()>0);float fit=Math.min(view.getWidth()/1000f,view.getHeight()/500f),left=(view.getWidth()-1000*fit)/2,top=(view.getHeight()-500*fit)/2;long now=android.os.SystemClock.uptimeMillis();float[][] points={{left+50*fit,top+25*fit},{left+350*fit,top+180*fit},{left+350*fit,top+180*fit}};int[] actions={MotionEvent.ACTION_DOWN,MotionEvent.ACTION_MOVE,MotionEvent.ACTION_UP};for(int i=0;i<3;i++){MotionEvent event=MotionEvent.obtain(now,now+i*20,actions[i],points[i][0],points[i][1],0);try{assertTrue(view.dispatchTouchEvent(event));}finally{event.recycle();}}assertEquals("ONE",view.selection.text());assertEquals(Color.RED,scan.image.getPixel(900,400));});}
 @Test public void selectedVisualAreaIsPixelsNotAnEmojiRecognitionClaim(){RectF[] chosen={null};show(text->fail("unexpected text save"),box->chosen[0]=box);click("Keep selected image");assertEquals(new RectF(0,0,1,1),chosen[0]);assertEquals(Color.RED,scan.image.getPixel(900,400));}
 @Test public void dismissingPreviewDoesNotExtractOrModifyAnything(){boolean[] changed={false};show(text->changed[0]=true,box->changed[0]=true);click("Close image selection");assertFalse(changed[0]);assertFalse(scan.image.isRecycled());}
 @Test public void closeWaitsForCropLeaseAndIsIdempotent(){assertTrue(scan.retain());scan.close();scan.close();assertFalse(scan.image.isRecycled());assertFalse(scan.retain());scan.release();assertTrue(scan.image.isRecycled());}
 @Test public void unsupportedPlaybackStillReportsAnErrorAndCanBeDisposed(){String[] message={null};main(()->{java.io.File missing=new java.io.File(activity.getCacheDir(),"missing-"+UUID.randomUUID()+".wav");VoicePlaybackCard card=new VoicePlaybackCard(new NotesDesign(activity,false),missing,"DONE","",0,()->{},text->message[0]=text,()->{},()->{},()->{});CheckBox boost=(CheckBox)named(card,"Boost quiet playback (+6 dB)");assertNotNull(boost);assertFalse(boost.isChecked());boost.setChecked(true);View play=named(card,"Play");assertNotNull(play);play.performClick();assertNotNull(message[0]);assertTrue(message[0].contains("original"));card.pause();card.dispose();card.dispose();assertFalse(missing.exists());});}
 private void await(java.util.function.BooleanSupplier ready)throws Exception{java.util.concurrent.CountDownLatch done=new java.util.concurrent.CountDownLatch(1);java.util.concurrent.atomic.AtomicBoolean stopped=new java.util.concurrent.atomic.AtomicBoolean();activity.runOnUiThread(new Runnable(){public void run(){if(stopped.get())return;if(ready.getAsBoolean())done.countDown();else activity.getWindow().getDecorView().postDelayed(this,25);}});try{assertTrue("Selection journey timed out",done.await(15,java.util.concurrent.TimeUnit.SECONDS));}finally{stopped.set(true);}}
 private app.space.notes.domain.Note review()throws Exception{
  fixture=new java.io.File(activity.getCacheDir(),"lens-"+UUID.randomUUID());assertTrue(fixture.mkdirs());isolated=new ContextWrapper(activity){@Override public Context getApplicationContext(){return this;}@Override public java.io.File getFilesDir(){return fixture;}@Override public SharedPreferences getSharedPreferences(String name,int mode){return activity.getSharedPreferences(fixture.getName()+name,mode);}};
  app.space.notes.domain.Note seed=app.space.notes.domain.Note.create(10).edit("Original","Keep this body",10);new NotesRepository(isolated).save(Collections.singletonList(seed));NotesHost host=new NotesHost(){public void showMessage(String value){messages.add(value);}public void chooseLocalFolder(){}public void openExistingFolder(){}public void exportBackup(){}public void importBackup(){}public String versionLabel(){return "Selection test";}public void shareText(String title,String value){}};
  main(()->{controller=new NotesController(isolated,host,null);activity.setContentView(controller.view());controller.openNote(seed.id);});await(()->named(controller.view(),"Original")!=null);
  main(()->{try{for(String name:new String[]{"title","body","search"}){java.lang.reflect.Field field=NotesController.class.getDeclaredField(name);field.setAccessible(true);field.set(controller,null);}java.lang.reflect.Field panel=NotesController.class.getDeclaredField("ocrPanel");panel.setAccessible(true);panel.setBoolean(controller,true);java.lang.reflect.Method render=NotesController.class.getDeclaredMethod("renderOcrReview",OfflineOcr.Result.class,String.class);render.setAccessible(true);render.invoke(controller,scan.result,seed.id);java.lang.reflect.Field active=NotesController.class.getDeclaredField("ocrScan");active.setAccessible(true);active.set(controller,scan);java.lang.reflect.Method add=NotesController.class.getDeclaredMethod("addOcrImageSelection",OfflineOcr.Scan.class,String.class);add.setAccessible(true);add.invoke(controller,scan,seed.id);View select=named(controller.view(),"Select from image");assertNotNull(select);java.lang.reflect.Field shown=NotesController.class.getDeclaredField("ocrSelectionDialog");shown.setAccessible(true);dialog=(Dialog)shown.get(controller);assertNotNull("Image selection opens immediately after scan",dialog);assertTrue(dialog.isShowing());}catch(ReflectiveOperationException failure){throw new AssertionError(failure);}});instrumentation.waitForIdleSync();return seed;
 }
 private EditText reviewInput(View root){if(root instanceof EditText && "Recognized text — edit before saving".contentEquals(((EditText)root).getHint()))return (EditText)root;if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++){EditText found=reviewInput(((ViewGroup)root).getChildAt(i));if(found!=null)return found;}return null;}
 @Test public void controllerSelectionChangesOnlyReviewUntilExplicitAppend()throws Exception{
  app.space.notes.domain.Note seed=review();byte[] before=DocumentCodec.encode(new NotesRepository(isolated).load());click("Clear");main(()->{ImageTextSelectionView view=viewport(dialog.getWindow().getDecorView());view.selection.toggle(1);view.refresh();});captureSelection();click("Use selected text");main(()->assertEquals("25",reviewInput(controller.view()).getText().toString()));assertArrayEquals(before,DocumentCodec.encode(new NotesRepository(isolated).load()));main(()->named(controller.view(),"Append to note").performClick());await(()->{try{return new NotesRepository(isolated).load().get(0).body.equals("Keep this body\n\n25");}catch(Exception e){return false;}});persisted();assertEquals(seed.id,new NotesRepository(isolated).load().get(0).id);assertTrue(scan.image.isRecycled());
 }
 @Test public void controllerVisualCopySavesAnEmbeddedImageAndKeepsBody()throws Exception{
  app.space.notes.domain.Note seed=review();click("Keep selected image");await(()->{try{return new NotesRepository(isolated).load().get(0).images.size()==1;}catch(Exception e){return false;}});persisted();app.space.notes.domain.Note saved=new NotesRepository(isolated).load().get(0);assertEquals(seed.id,saved.id);assertEquals("Keep this body",saved.body);assertEquals(1,saved.images.size());Bitmap decoded=NoteImageFiles.decode(saved.images.get(0));assertNotNull(decoded);try{assertEquals(Color.RED,decoded.getPixel(900,400));}finally{decoded.recycle();}assertEquals(1,new NotesRepository(isolated).load().size());
 }
 @Test public void controllerBackReleasesPreviewAndKeepsSavedData()throws Exception{
  review();byte[] before=DocumentCodec.encode(new NotesRepository(isolated).load());click("Close image selection");main(controller::back);assertArrayEquals(before,DocumentCodec.encode(new NotesRepository(isolated).load()));assertTrue(scan.image.isRecycled());
 }

 @Test public void emptyTextStillAllowsVisualSelectionWithoutInventedWords(){scan.close();Bitmap blank=Bitmap.createBitmap(100,100,Bitmap.Config.ARGB_8888);new Canvas(blank).drawColor(Color.GREEN);scan=new OfflineOcr.Scan(new OfflineOcr.Result("","auto",0,100,100),blank);show(text->fail("No text should be invented"),box->{});main(()->{View root=dialog.getWindow().getDecorView();assertFalse(named(root,"Use selected text").isEnabled());assertTrue(named(root,"Keep selected image").isEnabled());assertEquals("",viewport(root).selection.text());});}

 private void captureSelection()throws Exception{instrumentation.waitForIdleSync();java.util.concurrent.CountDownLatch frames=new java.util.concurrent.CountDownLatch(1);main(()->dialog.getWindow().getDecorView().postOnAnimation(()->dialog.getWindow().getDecorView().postOnAnimation(frames::countDown)));assertTrue(frames.await(5,java.util.concurrent.TimeUnit.SECONDS));instrumentation.waitForIdleSync();Bitmap shot=instrumentation.getUiAutomation().takeScreenshot();assertNotNull(shot);java.io.File directory=new java.io.File(instrumentation.getTargetContext().getFilesDir(),"ux-review");if(!directory.isDirectory())assertTrue(directory.mkdirs());try(java.io.OutputStream out=new java.io.FileOutputStream(new java.io.File(directory,"image-text-selection.png"))){assertTrue(shot.compress(Bitmap.CompressFormat.PNG,100,out));}finally{shot.recycle();}}

 private void persisted()throws Exception{await(()->{try{java.lang.reflect.Field revision=NotesController.class.getDeclaredField("revision"),saved=NotesController.class.getDeclaredField("persistedRevision");revision.setAccessible(true);saved.setAccessible(true);return revision.getLong(controller)>0 && saved.getLong(controller)>=revision.getLong(controller);}catch(ReflectiveOperationException invalid){throw new AssertionError(invalid);}});for(String message:messages)assertFalse(message,message.startsWith("Save incomplete"));}

 @Test public void transparentPreviewUsesWhiteWithoutChangingSourcePixels(){scan.close();Bitmap original=Bitmap.createBitmap(100,100,Bitmap.Config.ARGB_8888);scan=new OfflineOcr.Scan(new OfflineOcr.Result("","auto",0,100,100),original);show(text->{},box->{});main(()->{ImageTextSelectionView view=viewport(dialog.getWindow().getDecorView());assertTrue(view.getWidth()>0 && view.getHeight()>0);Bitmap rendered=Bitmap.createBitmap(view.getWidth(),view.getHeight(),Bitmap.Config.ARGB_8888);try{view.draw(new Canvas(rendered));assertEquals(Color.WHITE,rendered.getPixel(rendered.getWidth()/2,rendered.getHeight()/2));assertEquals(Color.TRANSPARENT,original.getPixel(50,50));}finally{rendered.recycle();}});}

 @Test public void selectionViewportRetainsUsefulAreaInPortraitAndLandscape()throws Exception{show(text->{},box->{});await(()->viewport(dialog.getWindow().getDecorView()).getHeight()>0);main(()->{View root=dialog.getWindow().getDecorView();ImageTextSelectionView image=viewport(root);assertTrue("Image preview must not be a strip between fixed controls",image.getHeight()>=root.getHeight()*.35f);boolean wide=activity.getResources().getConfiguration().orientation==android.content.res.Configuration.ORIENTATION_LANDSCAPE;if(!wide){View preview=named(root,"Selected text preview"),ancestor=preview;while(ancestor!=null && !(ancestor instanceof ScrollView))ancestor=ancestor.getParent() instanceof View?(View)ancestor.getParent():null;assertNotNull("Secondary selection details remain in a vertical scroller",ancestor);assertTrue("Secondary details cannot consume an unbounded share of the portrait viewport",ancestor.getHeight()<=Math.round(160*activity.getResources().getDisplayMetrics().density)+1);assertNotSame("Primary reading action remains pinned outside secondary details",ancestor,named(root,"Read this area").getParent());}for(String action:new String[]{"Use selected text","Keep selected image","Read this area"}){View button=named(root,action);assertNotNull(button);Rect visible=new Rect();assertTrue("Primary action remains visible without scrolling: "+action,button.getGlobalVisibleRect(visible));assertEquals("Primary action is not clipped: "+action,button.getHeight(),visible.height());}});}
 @Test public void retainedDialogReflowsBothWaysWithoutLosingSelectionOrBitmap()throws Exception{
  show(text->{},box->{});final ImageTextSelectionView[] original={null};final int[] requested={0};
  main(()->{original[0]=viewport(dialog.getWindow().getDecorView());original[0].selection.all(false);original[0].selection.toggle(1);original[0].refresh();requested[0]=activity.getRequestedOrientation();});
  try{for(int direction:new int[]{android.content.pm.ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE,android.content.pm.ActivityInfo.SCREEN_ORIENTATION_PORTRAIT}){
   main(()->activity.setRequestedOrientation(direction));boolean wide=direction==android.content.pm.ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE;
   await(()->{View root=dialog.getWindow().getDecorView();ImageTextSelectionView image=viewport(root);return (root.getWidth()>root.getHeight())==wide && image!=null && ((LinearLayout)image.getParent()).getOrientation()==(wide?LinearLayout.HORIZONTAL:LinearLayout.VERTICAL);});
   main(()->{assertTrue(dialog.isShowing());ImageTextSelectionView image=viewport(dialog.getWindow().getDecorView());assertSame(original[0],image);assertEquals("25",image.selection.text());assertEquals(new RectF(0,0,1,1),image.crop());assertFalse(scan.image.isRecycled());for(String name:new String[]{"Use selected text","Keep selected image"}){View action=named(dialog.getWindow().getDecorView(),name);assertNotNull(action);Rect visible=new Rect();assertTrue(name,action.getGlobalVisibleRect(visible));assertEquals(name+" wide="+wide+" "+geometryChain(action),action.getHeight(),visible.height());}});
  }}finally{main(()->activity.setRequestedOrientation(requested[0]));}
 }
 private static String geometryChain(View action){StringBuilder out=new StringBuilder();for(View v=action;v!=null;v=v.getParent() instanceof View?(View)v.getParent():null){Rect visible=new Rect();v.getGlobalVisibleRect(visible);out.append(v.getClass().getSimpleName()).append(" bounds=").append(v.getLeft()).append(',').append(v.getTop()).append(',').append(v.getRight()).append(',').append(v.getBottom()).append(" measured=").append(v.getMeasuredWidth()).append('x').append(v.getMeasuredHeight()).append(" visible=").append(visible).append(" pending=").append(v.isLayoutRequested()).append("; ");}return out.toString();}
 @Test public void reviewFieldsAndSaveStayReachableInReducedViewport()throws Exception{
  review();click("Close image selection");final int[] oldHeight={0};main(()->{View root=controller.view();ViewGroup.LayoutParams lp=root.getLayoutParams();oldHeight[0]=lp.height;lp.height=Math.round(180*activity.getResources().getDisplayMetrics().density);root.setLayoutParams(lp);});try{await(()->controller.view().getHeight()<=Math.round(180*activity.getResources().getDisplayMetrics().density));main(()->{EditText input=reviewInput(controller.view());View parent=(View)input.getParent();assertTrue(parent.getParent() instanceof ScrollView);assertTrue(((ScrollView)parent.getParent()).getHeight()>0);input.requestRectangleOnScreen(new Rect(0,0,input.getWidth(),Math.min(input.getHeight(),48)),true);Rect visible=new Rect();assertTrue(input.getGlobalVisibleRect(visible));assertTrue(visible.height()>0);View save=named(controller.view(),"Append to note");assertNotNull(save);save.requestRectangleOnScreen(new Rect(0,0,save.getWidth(),save.getHeight()),true);assertTrue(save.getGlobalVisibleRect(visible));assertTrue(visible.height()>0);assertTrue(save.isEnabled());});assertEquals("Keep this body",new NotesRepository(isolated).load().get(0).body);}finally{main(()->{ViewGroup.LayoutParams lp=controller.view().getLayoutParams();lp.height=oldHeight[0];controller.view().setLayoutParams(lp);});}
 }

}
